CREATE DATABASE IF NOT EXISTS wellness_centre CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wellness_centre;

CREATE TABLE roles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, display_name VARCHAR(150) NOT NULL, user_type ENUM('client','staff') NOT NULL, status ENUM('active','locked','inactive') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE social_identity_links (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(40) NOT NULL, provider_subject VARCHAR(191) NOT NULL, UNIQUE KEY provider_identity(provider,provider_subject), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE staff_accounts (user_id BIGINT UNSIGNED PRIMARY KEY, role_id BIGINT UNSIGNED NOT NULL, password_hash VARCHAR(255) NULL, mfa_enabled BOOLEAN DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE locations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,timezone VARCHAR(64) NOT NULL DEFAULT 'America/Toronto');
CREATE TABLE practitioners (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,location_id BIGINT UNSIGNED NOT NULL,discipline VARCHAR(100),bio TEXT,credentials VARCHAR(255),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE rooms (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,location_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,room_type VARCHAR(80),capabilities JSON,turnover_minutes SMALLINT UNSIGNED DEFAULT 0,is_bookable BOOLEAN DEFAULT TRUE,FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE services (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,practitioner_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,duration_minutes SMALLINT UNSIGNED NOT NULL,price_cents INT UNSIGNED NOT NULL,requires_room BOOLEAN DEFAULT TRUE,recurrence_allowed BOOLEAN DEFAULT FALSE,FOREIGN KEY(practitioner_id) REFERENCES practitioners(id),CHECK (duration_minutes % 15 = 0));
CREATE TABLE availability_rules (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,practitioner_id BIGINT UNSIGNED NOT NULL,weekday TINYINT UNSIGNED NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(practitioner_id) REFERENCES practitioners(id));
CREATE TABLE time_off (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,practitioner_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,reason ENUM('vacation','sick','block') NOT NULL,FOREIGN KEY(practitioner_id) REFERENCES practitioners(id));
CREATE TABLE appointments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,client_id BIGINT UNSIGNED NOT NULL,practitioner_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,room_id BIGINT UNSIGNED NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status ENUM('draft','requested','confirmed','rescheduled','canceled_by_client','canceled_by_clinic','no_show','completed','invoiced','paid') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(practitioner_id) REFERENCES practitioners(id),FOREIGN KEY(service_id) REFERENCES services(id),FOREIGN KEY(room_id) REFERENCES rooms(id),INDEX schedule_lookup(practitioner_id,starts_at,ends_at),INDEX room_lookup(room_id,starts_at,ends_at));
CREATE TABLE appointment_status_history (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,appointment_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL,actor_user_id BIGINT UNSIGNED NULL,reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointments(id),FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE TABLE waitlist_entries (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,client_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,practitioner_id BIGINT UNSIGNED NULL,preferred_days JSON,expires_at DATETIME NULL,status ENUM('active','offered','accepted','expired','removed') DEFAULT 'active',FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE invoices (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,client_id BIGINT UNSIGNED NOT NULL,appointment_id BIGINT UNSIGNED NULL,number VARCHAR(40) NOT NULL UNIQUE,status ENUM('draft','issued','paid','void','refunded') NOT NULL DEFAULT 'draft',subtotal_cents INT UNSIGNED NOT NULL,tax_cents INT UNSIGNED NOT NULL DEFAULT 0,balance_cents INT UNSIGNED NOT NULL,FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(appointment_id) REFERENCES appointments(id));
CREATE TABLE payments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT UNSIGNED NOT NULL,amount_cents INT UNSIGNED NOT NULL,method VARCHAR(40) NOT NULL,status ENUM('recorded','refunded','failed') DEFAULT 'recorded',paid_at DATETIME NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE consent_records (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,client_id BIGINT UNSIGNED NOT NULL,purpose VARCHAR(190) NOT NULL,accepted_at DATETIME NOT NULL,withdrawn_at DATETIME NULL,FOREIGN KEY(client_id) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX audit_entity(entity_type,entity_id),FOREIGN KEY(actor_user_id) REFERENCES users(id));
INSERT INTO roles(name) VALUES ('super_admin'),('clinic_admin'),('reception'),('practitioner'),('accountant');
